// Dia do ano (1 a 366) no fuso local, usado como índice estável durante o dia.
function diaDoAno(data) {
  const inicio = new Date(data.getFullYear(), 0, 1);
  const diff = data - inicio;
  return Math.floor(diff / 86400000) + 1;
}

// Versículo/frase de hoje — o mesmo o dia inteiro, muda só quando vira o dia.
export function versiculoDoDia(data = new Date()) {
  const idx = (diaDoAno(data) - 1) % VERSICULOS_DO_DIA.length;
  return VERSICULOS_DO_DIA[idx];
}
